class RingBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self.buffer = [None] * capacity
        self.head = 0
        self.count = 0

    def order(self, name):
        if self.count < self.capacity:
            self.buffer[(self.head + self.count) % self.capacity] = name
            self.count += 1
        else:
            self.buffer[self.head] = name
            self.head = (self.head + 1) % self.capacity

    def display(self):
        for i in range(self.count):
            print(self.buffer[(self.head + i) % self.capacity])


rb = RingBuffer(3)
operations = [
    "latte",
    "cappuccino",
    "espresso",
    "mocha",
    "americano",
    "flat white",
    "cortado",
]
for op in operations:
    rb.order(op)
rb.display()

boards = [
    [("Alice", 90), ("Bob", 75)],
    [("Carol", 60), ("Dave", 100)],
    [("Eve", 45), ("Frank", 50)],
    [("Grace", 120), ("Henry", 40)],
]
rounds = [30, 45, 60]
order = ["Alice", "Bob", "Carol", "Dave", "Eve", "Frank", "Grace", "Henry"]
clocks = {name: c for b in boards for name, c in b}
lost = set()

for r, length in enumerate(rounds, 1):
    losers = []
    for board in boards:
        board_losers = []
        for name, _ in board:
            if name in lost:
                continue
            if clocks[name] - length < 0:
                clocks[name] = 0
                lost.add(name)
                board_losers.append(name)
        for name in board_losers:
            losers.append(name)
        for name, _ in board:
            if name in lost:
                continue
            clocks[name] -= length
    print(f"R{r} " + (",".join(losers) if losers else "none"))

for name in order:
    print(f"{name} {clocks[name]}")
